// Generated by ipadport. Native implementations of the `window.ipadport` JavaScript API, plus the
// web view delegates that make alert/confirm/prompt, links, popups and downloads behave on iOS.

import UIKit
import UniformTypeIdentifiers
import UserNotifications
import WebKit

enum BridgeError: LocalizedError {
    case message(String)
    var errorDescription: String? {
        switch self {
        case .message(let text): return text
        }
    }
}

/// The app's private file area. JavaScript paths like "/notes/a.txt" (or desktop paths such as
/// "C:\Users\me\notes\a.txt") are mapped to <app Documents>/notes/a.txt. Documents is visible in the Files app.
enum Sandbox {
    static var root: URL {
        FileManager.default.urls(for: .documentDirectory, in: .userDomainMask)[0].standardizedFileURL
    }

    static func resolve(_ rawPath: String) throws -> URL {
        var path = rawPath.replacingOccurrences(of: "\\", with: "/")
        if path.hasPrefix("file://"), let url = URL(string: path) { path = url.path }
        if path.count >= 2, path[path.index(path.startIndex, offsetBy: 1)] == ":" {
            path = String(path.dropFirst(2))  // drop a Windows drive letter
        }
        let rootPath = root.path
        if path.hasPrefix(rootPath) { path = String(path.dropFirst(rootPath.count)) }
        while path.hasPrefix("/") { path.removeFirst() }
        let url = path.isEmpty ? root : root.appendingPathComponent(path).standardizedFileURL
        guard url.path == rootPath || url.path.hasPrefix(rootPath + "/") else {
            throw BridgeError.message("Path is outside the app sandbox: \(rawPath)")
        }
        return url
    }

    static func virtualPath(_ url: URL) -> String {
        let full = url.standardizedFileURL.path
        let rootPath = root.path
        guard full.hasPrefix(rootPath) else { return full }
        let rest = full.dropFirst(rootPath.count)
        return rest.isEmpty ? "/" : String(rest)
    }

    static func uniqueURL(in directory: URL, name: String) -> URL {
        var candidate = directory.appendingPathComponent(name)
        let base = candidate.deletingPathExtension().lastPathComponent
        let ext = candidate.pathExtension
        var index = 2
        while FileManager.default.fileExists(atPath: candidate.path) {
            let numbered = ext.isEmpty ? "\(base) \(index)" : "\(base) \(index).\(ext)"
            candidate = directory.appendingPathComponent(numbered)
            index += 1
        }
        return candidate
    }
}

@MainActor
final class NativeBridge: NSObject, WKScriptMessageHandlerWithReply, WKNavigationDelegate, WKUIDelegate,
    WKDownloadDelegate, UIDocumentPickerDelegate {

    weak var webView: WKWebView?
    private let store = UserDefaults(suiteName: "ipadport.store") ?? .standard
    private var pickerCompletion: (([URL]) -> Void)?
    private var downloadDestinations: [ObjectIdentifier: URL] = [:]
    static let syncPromptPrefix = "__ipadport_sync__"

    @objc func reload(_ sender: UIRefreshControl) {
        webView?.reload()
        sender.endRefreshing()
    }

    // MARK: - JavaScript -> native (async, Promise based)

    func userContentController(_ userContentController: WKUserContentController, didReceive message: WKScriptMessage,
                               replyHandler: @escaping (Any?, String?) -> Void) {
        guard let body = message.body as? [String: Any], let method = body["method"] as? String else {
            replyHandler(nil, "Invalid ipadport bridge call")
            return
        }
        let args = body["args"] as? [String: Any] ?? [:]
        handleAsync(method, args) { result in
            switch result {
            case .success(let value): replyHandler(value ?? NSNull(), nil)
            case .failure(let error): replyHandler(nil, error.localizedDescription)
            }
        }
    }

    private func handleAsync(_ method: String, _ args: [String: Any], _ done: @escaping (Result<Any?, Error>) -> Void) {
        switch method {
        case "dialog.open":
            presentDocumentPicker(multiple: args["multiple"] as? Bool ?? false,
                                  directory: args["directory"] as? Bool ?? false,
                                  extensions: args["extensions"] as? [String] ?? []) { urls in
                done(.success(urls.map { Sandbox.virtualPath($0) }))
            }
        case "dialog.message":
            presentAlert(title: args["title"] as? String, message: args["message"] as? String ?? "",
                         detail: args["detail"] as? String, buttons: args["buttons"] as? [String] ?? ["OK"],
                         cancelId: args["cancelId"] as? Int) { index in
                done(.success(index))
            }
        case "share":
            var items: [Any] = []
            if let text = args["text"] as? String { items.append(text) }
            if let link = args["url"] as? String, let url = URL(string: link) { items.append(url) }
            if let path = args["path"] as? String {
                do { items.append(try Sandbox.resolve(path)) } catch { done(.failure(error)); return }
            }
            presentShareSheet(items)
            done(.success(true))
        case "shell.openExternal":
            guard let link = args["url"] as? String, let url = URL(string: link) else {
                done(.failure(BridgeError.message("Invalid URL")))
                return
            }
            UIApplication.shared.open(url, options: [:]) { ok in done(.success(ok)) }
        case "notification.show":
            showNotification(title: args["title"] as? String ?? "", body: args["body"] as? String ?? "")
            done(.success(true))
        default:
            do { done(.success(try handleSync(method, args))) } catch { done(.failure(error)) }
        }
    }

    // MARK: - Synchronous calls (also reachable from JS synchronously through the prompt() channel)

    func handleSync(_ method: String, _ args: [String: Any]) throws -> Any? {
        let fm = FileManager.default
        func path(_ key: String = "path") throws -> URL {
            guard let value = args[key] as? String else { throw BridgeError.message("Missing argument '\(key)'") }
            return try Sandbox.resolve(value)
        }
        func notFound(_ url: URL) -> BridgeError {
            .message("ENOENT: no such file or directory, '\(Sandbox.virtualPath(url))'")
        }

        switch method {
        case "platform.info":
            let info = Bundle.main.infoDictionary ?? [:]
            return [
                "platform": "ios",
                "idiom": UIDevice.current.userInterfaceIdiom == .pad ? "pad" : "phone",
                "systemVersion": UIDevice.current.systemVersion,
                "appVersion": info["CFBundleShortVersionString"] as? String ?? "1.0",
                "appName": info["CFBundleDisplayName"] as? String ?? info["CFBundleName"] as? String ?? "",
                "locale": Locale.preferredLanguages.first ?? "en",
                "documents": Sandbox.root.path,
            ]

        // Clipboard
        case "clipboard.readText":
            return UIPasteboard.general.string ?? ""
        case "clipboard.writeText":
            UIPasteboard.general.string = args["text"] as? String ?? ""
            return true
        case "clipboard.clear":
            UIPasteboard.general.items = []
            return true

        // Key-value store (values are JSON strings written by the shim)
        case "store.get":
            return store.string(forKey: args["key"] as? String ?? "")
        case "store.set":
            store.set(args["value"] as? String, forKey: args["key"] as? String ?? "")
            return true
        case "store.delete":
            store.removeObject(forKey: args["key"] as? String ?? "")
            return true
        case "store.all":
            let domain = store.persistentDomain(forName: "ipadport.store") ?? [:]
            return domain.compactMapValues { $0 as? String }
        case "store.clear":
            store.removePersistentDomain(forName: "ipadport.store")
            return true

        // File system (sandboxed)
        case "fs.readFile":
            let url = try path()
            guard let data = fm.contents(atPath: url.path) else { throw notFound(url) }
            if (args["encoding"] as? String) == "base64" { return data.base64EncodedString() }
            return String(decoding: data, as: UTF8.self)
        case "fs.writeFile", "fs.appendFile":
            let url = try path()
            let text = args["data"] as? String ?? ""
            let data = (args["encoding"] as? String) == "base64" ? (Data(base64Encoded: text) ?? Data()) : Data(text.utf8)
            try fm.createDirectory(at: url.deletingLastPathComponent(), withIntermediateDirectories: true)
            if method == "fs.appendFile", let handle = try? FileHandle(forWritingTo: url) {
                defer { try? handle.close() }
                try handle.seekToEnd()
                try handle.write(contentsOf: data)
            } else {
                try data.write(to: url, options: .atomic)
            }
            return true
        case "fs.exists":
            return fm.fileExists(atPath: try path().path)
        case "fs.stat":
            let url = try path()
            guard fm.fileExists(atPath: url.path) else { throw notFound(url) }
            let attributes = try fm.attributesOfItem(atPath: url.path)
            let isDirectory = (attributes[.type] as? FileAttributeType) == .typeDirectory
            let modified = (attributes[.modificationDate] as? Date) ?? Date()
            let created = (attributes[.creationDate] as? Date) ?? modified
            return [
                "size": (attributes[.size] as? NSNumber)?.intValue ?? 0,
                "isDirectory": isDirectory,
                "isFile": !isDirectory,
                "mtimeMs": modified.timeIntervalSince1970 * 1000,
                "birthtimeMs": created.timeIntervalSince1970 * 1000,
            ]
        case "fs.readdir":
            let url = try path()
            guard fm.fileExists(atPath: url.path) else { throw notFound(url) }
            return try fm.contentsOfDirectory(atPath: url.path).sorted()
        case "fs.mkdir":
            try fm.createDirectory(at: try path(), withIntermediateDirectories: args["recursive"] as? Bool ?? true)
            return true
        case "fs.unlink", "fs.rm", "fs.rmdir":
            let url = try path()
            if fm.fileExists(atPath: url.path) {
                try fm.removeItem(at: url)
            } else if !(args["force"] as? Bool ?? false) {
                throw notFound(url)
            }
            return true
        case "fs.rename":
            let from = try path("from"), to = try path("to")
            try fm.createDirectory(at: to.deletingLastPathComponent(), withIntermediateDirectories: true)
            if fm.fileExists(atPath: to.path) { try fm.removeItem(at: to) }
            try fm.moveItem(at: from, to: to)
            return true
        case "fs.copyFile":
            let from = try path("from"), to = try path("to")
            try fm.createDirectory(at: to.deletingLastPathComponent(), withIntermediateDirectories: true)
            if fm.fileExists(atPath: to.path) { try fm.removeItem(at: to) }
            try fm.copyItem(at: from, to: to)
            return true
        case "app.quit":
            return true  // iOS apps are closed by the user, not by themselves.
        default:
            throw BridgeError.message("Unknown ipadport method: \(method)")
        }
    }

    // MARK: - UI helpers

    private var presenter: UIViewController? {
        let scene = webView?.window?.windowScene
            ?? UIApplication.shared.connectedScenes.compactMap { $0 as? UIWindowScene }.first
        var top = scene?.windows.first(where: { $0.isKeyWindow })?.rootViewController ?? scene?.windows.first?.rootViewController
        while let presented = top?.presentedViewController { top = presented }
        return top
    }

    private func anchorPopover(_ controller: UIViewController) {
        if let popover = controller.popoverPresentationController, let view = webView {
            popover.sourceView = view
            popover.sourceRect = CGRect(x: view.bounds.midX, y: view.bounds.midY, width: 1, height: 1)
            popover.permittedArrowDirections = []
        }
    }

    private func presentAlert(title: String?, message: String, detail: String?, buttons: [String], cancelId: Int?,
                              completion: @escaping (Int) -> Void) {
        let text = [message, detail].compactMap { $0 }.filter { !$0.isEmpty }.joined(separator: "\n\n")
        let alert = UIAlertController(title: title, message: text, preferredStyle: .alert)
        let labels = buttons.isEmpty ? ["OK"] : buttons
        for (index, label) in labels.enumerated() {
            let style: UIAlertAction.Style = index == cancelId ? .cancel : .default
            alert.addAction(UIAlertAction(title: label, style: style) { _ in completion(index) })
        }
        guard let presenter else { completion(cancelId ?? 0); return }
        presenter.present(alert, animated: true)
    }

    private func presentShareSheet(_ items: [Any]) {
        guard !items.isEmpty, let presenter else { return }
        let sheet = UIActivityViewController(activityItems: items, applicationActivities: nil)
        anchorPopover(sheet)
        presenter.present(sheet, animated: true)
    }

    private func presentDocumentPicker(multiple: Bool, directory: Bool, extensions: [String],
                                       completion: @escaping ([URL]) -> Void) {
        var types: [UTType] = extensions.compactMap { UTType(filenameExtension: $0.trimmingCharacters(in: CharacterSet(charactersIn: "."))) }
        if directory { types = [.folder] }
        if types.isEmpty { types = [.item] }
        let picker = UIDocumentPickerViewController(forOpeningContentTypes: types, asCopy: !directory)
        picker.allowsMultipleSelection = multiple
        picker.delegate = self
        pickerCompletion = completion
        guard let presenter else { completion([]); return }
        presenter.present(picker, animated: true)
    }

    func documentPicker(_ controller: UIDocumentPickerViewController, didPickDocumentsAt urls: [URL]) {
        let importDir = Sandbox.root.appendingPathComponent("Imported", isDirectory: true)
        try? FileManager.default.createDirectory(at: importDir, withIntermediateDirectories: true)
        var results: [URL] = []
        for url in urls {
            let scoped = url.startAccessingSecurityScopedResource()
            defer { if scoped { url.stopAccessingSecurityScopedResource() } }
            let destination = Sandbox.uniqueURL(in: importDir, name: url.lastPathComponent)
            if (try? FileManager.default.copyItem(at: url, to: destination)) != nil {
                results.append(destination)
            }
        }
        pickerCompletion?(results)
        pickerCompletion = nil
    }

    func documentPickerWasCancelled(_ controller: UIDocumentPickerViewController) {
        pickerCompletion?([])
        pickerCompletion = nil
    }

    private func showNotification(title: String, body: String) {
        let center = UNUserNotificationCenter.current()
        center.requestAuthorization(options: [.alert, .sound, .badge]) { granted, _ in
            guard granted else { return }
            let content = UNMutableNotificationContent()
            content.title = title
            content.body = body
            let request = UNNotificationRequest(identifier: UUID().uuidString, content: content, trigger: nil)
            center.add(request)
        }
    }

    // MARK: - WKUIDelegate: alert / confirm / prompt / window.open

    func webView(_ webView: WKWebView, runJavaScriptAlertPanelWithMessage message: String,
                 initiatedByFrame frame: WKFrameInfo, completionHandler: @escaping () -> Void) {
        let alert = UIAlertController(title: nil, message: message, preferredStyle: .alert)
        alert.addAction(UIAlertAction(title: "OK", style: .default) { _ in completionHandler() })
        guard let presenter else { completionHandler(); return }
        presenter.present(alert, animated: true)
    }

    func webView(_ webView: WKWebView, runJavaScriptConfirmPanelWithMessage message: String,
                 initiatedByFrame frame: WKFrameInfo, completionHandler: @escaping (Bool) -> Void) {
        let alert = UIAlertController(title: nil, message: message, preferredStyle: .alert)
        alert.addAction(UIAlertAction(title: "Cancel", style: .cancel) { _ in completionHandler(false) })
        alert.addAction(UIAlertAction(title: "OK", style: .default) { _ in completionHandler(true) })
        guard let presenter else { completionHandler(false); return }
        presenter.present(alert, animated: true)
    }

    func webView(_ webView: WKWebView, runJavaScriptTextInputPanelWithPrompt prompt: String, defaultText: String?,
                 initiatedByFrame frame: WKFrameInfo, completionHandler: @escaping (String?) -> Void) {
        if prompt == Self.syncPromptPrefix {
            completionHandler(syncCall(defaultText ?? "{}"))
            return
        }
        let alert = UIAlertController(title: nil, message: prompt, preferredStyle: .alert)
        alert.addTextField { $0.text = defaultText }
        alert.addAction(UIAlertAction(title: "Cancel", style: .cancel) { _ in completionHandler(nil) })
        alert.addAction(UIAlertAction(title: "OK", style: .default) { _ in completionHandler(alert.textFields?.first?.text) })
        guard let presenter else { completionHandler(nil); return }
        presenter.present(alert, animated: true)
    }

    private func syncCall(_ json: String) -> String {
        var response: [String: Any]
        do {
            guard let payload = try JSONSerialization.jsonObject(with: Data(json.utf8)) as? [String: Any],
                  let method = payload["method"] as? String else {
                throw BridgeError.message("Invalid synchronous bridge call")
            }
            let value = try handleSync(method, payload["args"] as? [String: Any] ?? [:])
            response = ["ok": true, "value": value ?? NSNull()]
        } catch {
            response = ["ok": false, "error": error.localizedDescription]
        }
        guard let data = try? JSONSerialization.data(withJSONObject: response) else {
            return "{\"ok\":false,\"error\":\"Could not encode result\"}"
        }
        return String(decoding: data, as: UTF8.self)
    }

    func webView(_ webView: WKWebView, createWebViewWith configuration: WKWebViewConfiguration,
                 for navigationAction: WKNavigationAction, windowFeatures: WKWindowFeatures) -> WKWebView? {
        // window.open / target=_blank: app pages open in place, everything else in Safari.
        if let url = navigationAction.request.url {
            if AppConfig.isInternal(url) {
                webView.load(navigationAction.request)
            } else if ["http", "https", "mailto", "tel", "sms"].contains(url.scheme?.lowercased() ?? "") {
                UIApplication.shared.open(url)
            }
        }
        return nil
    }

    // MARK: - WKNavigationDelegate: external links and downloads

    func webView(_ webView: WKWebView, decidePolicyFor navigationAction: WKNavigationAction,
                 decisionHandler: @escaping (WKNavigationActionPolicy) -> Void) {
        guard let url = navigationAction.request.url else { decisionHandler(.allow); return }
        if navigationAction.shouldPerformDownload {
            decisionHandler(.download)
            return
        }
        let isMainFrame = navigationAction.targetFrame?.isMainFrame ?? true
        let scheme = url.scheme?.lowercased() ?? ""
        if isMainFrame && !AppConfig.isInternal(url) && ["http", "https", "mailto", "tel", "sms", "facetime"].contains(scheme) {
            UIApplication.shared.open(url)
            decisionHandler(.cancel)
            return
        }
        decisionHandler(.allow)
    }

    func webView(_ webView: WKWebView, decidePolicyFor navigationResponse: WKNavigationResponse,
                 decisionHandler: @escaping (WKNavigationResponsePolicy) -> Void) {
        decisionHandler(navigationResponse.canShowMIMEType ? .allow : .download)
    }

    func webView(_ webView: WKWebView, navigationAction: WKNavigationAction, didBecome download: WKDownload) {
        download.delegate = self
    }

    func webView(_ webView: WKWebView, navigationResponse: WKNavigationResponse, didBecome download: WKDownload) {
        download.delegate = self
    }

    func webViewWebContentProcessDidTerminate(_ webView: WKWebView) {
        webView.reload()  // iOS may reclaim the web process under memory pressure.
    }

    // MARK: - WKDownloadDelegate: saves into Documents/Downloads, then offers the share sheet

    func download(_ download: WKDownload, decideDestinationUsing response: URLResponse, suggestedFilename: String,
                  completionHandler: @escaping (URL?) -> Void) {
        let directory = Sandbox.root.appendingPathComponent("Downloads", isDirectory: true)
        try? FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
        let destination = Sandbox.uniqueURL(in: directory, name: suggestedFilename)
        downloadDestinations[ObjectIdentifier(download)] = destination
        completionHandler(destination)
    }

    func downloadDidFinish(_ download: WKDownload) {
        if let url = downloadDestinations.removeValue(forKey: ObjectIdentifier(download)) {
            presentShareSheet([url])
        }
    }

    func download(_ download: WKDownload, didFailWithError error: Error, resumeData: Data?) {
        downloadDestinations.removeValue(forKey: ObjectIdentifier(download))
    }
}
